#pragma once
int runTrackMidi5229(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;try{
 auto require=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};require(checkExtractionPlayback420(true),"Track audition matches Stretch through UI lock contention");
 auto source=std::make_shared<AudioData>();source->rate=48000;source->path="retained-track.wav";source->buffer.setSize(1,48000);for(int n=0;n<48000;++n)source->buffer.setSample(0,n,.25f*std::sin(n*2*juce::MathConstants<double>::pi*220/48000));source->peakAmplitude=.25f;
 Processor p(false);p.autoSave=false;p.trackOffline=true;p.trackMode=p.stretchMode=true;p.audio=source;p.trackGridReady=true;p.trackStemsEnabled=false;p.extractionActive=p.extractionMidiAudition=p.sequenceEnabled=true;p.playMode=true;p.normaliseEnabled=false;p.swingEnabled=false;p.sequence.setLoop(0,4);p.sequence.notes={{1,60,100,1,0,.5}};p.sequence.changed();
 auto instrument=std::make_shared<Processor>(false);instrument->isContentionEngine=true;instrument->audio=source;instrument->oneShotMode=true;instrument->shotRootNote=60;instrument->normaliseEnabled=false;instrument->shotEnvelope={0,0,1,.001f};instrument->shotLoop=true;instrument->shotLoopEnd=48000;instrument->shotVelocity=100;instrument->prepareToPlay(48000,128);p.extractionInstrument=instrument;p.prepareToPlay(48000,128);p.sequenceMidiOut=true;
 struct Head:juce::AudioPlayHead{double beat=0;bool playing=true;juce::Optional<PositionInfo> getPosition()const override{PositionInfo x;x.setPpqPosition(beat);x.setBpm(120);x.setIsPlaying(playing);return x;}} head;p.setPlayHead(&head);juce::AudioBuffer<float> out(2,128);juce::MidiBuffer midi;double peak=0;int ons=0,offs=0;
 for(int block=0;block<300;++block){head.beat=block*128./24000;midi.clear();p.processBlock(out,midi);peak=juce::jmax(peak,(double)out.getMagnitude(0,128));for(auto e:midi){auto m=e.getMessage();ons+=m.isNoteOn();offs+=m.isNoteOff();}}require(peak>.01&&ons==1&&offs==1,"audible MIDI playback and one MIDI Out note-on/off");require(p.audio==source&&p.trackMode,"Track source remains loaded");
 head.playing=false;midi.clear();p.processBlock(out,midi);require(!p.sequenceWasPlaying,"transport stop releases sequencer");p.previewSequenceNote(60);midi.clear();p.processBlock(out,midi);require(out.getMagnitude(0,128)>.001,"stopped note audition");for(int n=0;n<100;++n){midi.clear();p.processBlock(out,midi);}require(out.getMagnitude(0,128)<.00001,"preview releases without stuck notes");
 p.sequenceEnabled=false;p.extractionMidiAudition=false;p.extractionPreviewActive=true;p.extractionPreviewInstrument=instrument;head.playing=true;head.beat=0;midi.clear();p.processBlock(out,midi);require(out.getMagnitude(0,128)>.001,"sound chooser preview plays sequence with retained Track");p.extractionPreviewActive=false;p.extractionPreviewInstrument.reset();p.setExtractionAudition(false);head.playing=false;midi.clear();p.processBlock(out,midi);require(p.audio==source&&p.trackMode,"Audio selection retains Track");p.setPlayHead(nullptr);
 auto file=LibraryStore::root().getChildFile("Track MIDI.mid");file.getParentDirectory().createDirectory();require(p.sequence.save(file),"MIDI fixture saved");require(p.loadSequence(file)&&p.audio==source&&p.trackMode&&p.extractionActive,"loading MIDI retains Track and enables audition controls");
 std::cout<<"5229 passed: Track retained during sequence playback, audition preview, stop/release, MIDI Out, MIDI loading and UI-lock fallback.\n";return 0;
 }catch(const std::exception& error){std::cerr<<"5229 failure: "<<error.what()<<"\n";return 1;}}
